    (19, "函数返回回文子串数。", "def count_palindromic(s):\n    count = 0\n    for i in range(len(s)):\n        for j in range(i, len(s)):\n            sub = s[i:j + 1]\n            if sub == sub[::-1]:\n                count += 1\n    return count\n\nprint('Count:', count_palindromic('aba'))", "填空回文计数。", "def count_palindromic(s):\n    count = 0\n    for i in range(len(s)):\n        for j in range(i, len(s)):\n            sub = s[i:j + 1]\n            if sub == sub[::-1]:\n                count += 1\n    return count\n\nprint('Count:', count_palindromic('aba'))"),
    (20, "函数返回成绩等级。", "def grade(score):\n    if score >= 90:\n        return \"A\"\n    elif score >= 80:\n        return \"B\"\n    else:\n        return \"C\"\n\nfor s in [92, 85, 70]:\n    print(f\"{s} -> {grade(s)}\")", "填空等级返回。", "def grade(score):\n    if score >= 90:\n        return \"A\"\n    elif score >= 80:\n        return \"B\"\n    else:\n        return \"C\"\n\nfor s in [92, 85, 70]:\n    print(f\"{s} -> {grade(s)}\")"),
