    (22, "函数返回组合数。", "def comb(n, k):\n    if k == 0 or k == n:\n        return 1\n    return comb(n - 1, k - 1) + comb(n - 1, k)\n\nprint('Comb:', comb(5, 2))", "填空组合返回。", "def comb(n, k):\n    if k == 0 or k == n:\n        return 1\n    return comb(n - 1, k - 1) + comb(n - 1, k)\n\nprint('Comb:', comb(5, 2))"),
    (23, "函数返回数字进制形式。", "def to_binary(n):\n    return bin(n)[2:]\n\nprint(to_binary(10))", "填空二进制返回。", "def to_binary(n):\n    return bin(n)[2:]\n\nprint(to_binary(10))"),
