    (25, "函数返回条件默认值。", "def validate(n, minimum=0):\n    if n < minimum:\n        return minimum\n    return n\n\nprint(validate(5), validate(-3, 0))", "填空校验返回。", "def validate(n, minimum=0):\n    if n < minimum:\n        return minimum\n    return n\n\nprint(validate(5), validate(-3, 0))"),
    (26, "函数返回列表平均值与中位数。", "def stats(nums):\n    avg = sum(nums) / len(nums)\n    sorted_nums = sorted(nums)\n    mid = len(sorted_nums) // 2\n    median = sorted_nums[mid]\n    return avg, median\n\na, m = stats([3, 1, 2])\nprint(round(a, 1), m)", "填空统计返回。", "def stats(nums):\n    avg = sum(nums) / len(nums)\n    sorted_nums = sorted(nums)\n    mid = len(sorted_nums) // 2\n    median = sorted_nums[mid]\n    return avg, median\n\na, m = stats([3, 1, 2])\nprint(round(a, 1), m)"),
    (27, "函数返回字符串中数字和。", "def digit_total(s):\n    return sum(int(c) for c in s if c.isdigit())\n\nprint('Sum:', digit_total('a1b2c3'))", "填空数字和返回。", "def digit_total(s):\n    return sum(int(c) for c in s if c.isdigit())\n\nprint('Sum:', digit_total('a1b2c3'))"),
