    (29, "函数返回最大递增差。", "def max_gain(prices):\n    min_price = prices[0]\n    max_profit = 0\n    for p in prices:\n        min_price = min(min_price, p)\n        max_profit = max(max_profit, p - min_price)\n    return max_profit\n\nprint('Gain:', max_gain([7, 1, 5, 3, 6, 4]))", "填空最大收益。", "def max_gain(prices):\n    min_price = prices[0]\n    max_profit = 0\n    for p in prices:\n        min_price = min(min_price, p)\n        max_profit = max(max_profit, p - min_price)\n    return max_profit\n\nprint('Gain:', max_gain([7, 1, 5, 3, 6, 4]))"),
